'use strict';
const path = require('path');
const fs = require('fs');
const http = require('http');
const crypto = require('crypto');
const os = require('os');
const express = require('express');
const Database = require('better-sqlite3');
const { WebSocketServer } = require('ws');

const ROOT = __dirname;
// Keep the database outside the project folder so replacing/updating the app never deletes accounts.
const platformDataRoot = process.env.NOVA_DATA_DIR || (process.platform === 'win32'
  ? path.join(process.env.APPDATA || path.join(os.homedir(), 'AppData', 'Roaming'), 'NovaMessenger')
  : path.join(process.env.HOME || ROOT, '.nova-messenger'));
const DATA = platformDataRoot;
fs.mkdirSync(DATA, { recursive: true });
const dbPath = path.join(DATA, 'nova.sqlite');
// Persistent database migration. The database lives in AppData, and when an update
// is started from a new extracted folder we also look for older Nova databases
// in nearby project folders. This prevents accounts from appearing to vanish.
function copySqlite(source, target) {
  fs.copyFileSync(source, target);
  for (const suffix of ['-wal','-shm']) {
    if (fs.existsSync(source + suffix)) fs.copyFileSync(source + suffix, target + suffix);
  }
}
function findLegacyDatabases() {
  const found = [];
  const seen = new Set();
  const add = p => {
    try {
      const r = path.resolve(p);
      if (!seen.has(r) && fs.existsSync(r) && fs.statSync(r).isFile()) { seen.add(r); found.push(r); }
    } catch {}
  };
  add(path.join(ROOT, 'data', 'nova.sqlite'));
  const parent = path.dirname(ROOT);
  try {
    for (const name of fs.readdirSync(parent)) {
      const dir = path.join(parent, name);
      try {
        if (!fs.statSync(dir).isDirectory()) continue;
        if (/^NovaMessenger/i.test(name)) add(path.join(dir, 'data', 'nova.sqlite'));
      } catch {}
    }
  } catch {}
  // Also check a common Downloads
  // location when the project was extracted into a new sibling folder.
  const downloads = path.join(os.homedir(), 'Downloads');
  try {
    for (const name of fs.readdirSync(downloads)) {
      const dir = path.join(downloads, name);
      try {
        if (!fs.statSync(dir).isDirectory()) continue;
        if (/^NovaMessenger/i.test(name)) add(path.join(dir, 'data', 'nova.sqlite'));
      } catch {}
    }
  } catch {}
  return found;
}

if (fs.existsSync(dbPath)) {
  // If AppData contains an empty database but an older project contains users,
  // replace the empty database with the populated legacy database.
  try {
    const probe = new Database(dbPath, { readonly: true });
    const hasUsersTable = !!probe.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='users'").get();
    const count = hasUsersTable ? probe.prepare('SELECT COUNT(*) AS n FROM users').get().n : 0;
    probe.close();
    if (Number(count) === 0) {
      const legacy = findLegacyDatabases().find(p => {
        try {
          const d = new Database(p, { readonly: true });
          const ok = !!d.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='users'").get();
          const n = ok ? d.prepare('SELECT COUNT(*) AS n FROM users').get().n : 0;
          d.close();
          return n > 0;
        } catch { return false; }
      });
      if (legacy) {
        fs.copyFileSync(dbPath, dbPath + '.empty-backup');
        for (const suffix of ['-wal','-shm']) { if (fs.existsSync(dbPath + suffix)) fs.copyFileSync(dbPath + suffix, dbPath + suffix + '.empty-backup'); }
        fs.rmSync(dbPath, { force: true });
        fs.rmSync(dbPath + '-wal', { force: true });
        fs.rmSync(dbPath + '-shm', { force: true });
        copySqlite(legacy, dbPath);
      }
    }
  } catch {}
} else {
  const legacy = findLegacyDatabases()[0];
  if (legacy) copySqlite(legacy, dbPath);
}

const db = new Database(dbPath);
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');
db.pragma('synchronous = NORMAL');
db.exec(`
CREATE TABLE IF NOT EXISTS users(
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 username TEXT NOT NULL UNIQUE COLLATE NOCASE,
 display_name TEXT NOT NULL,
 password_hash TEXT NOT NULL,
 salt TEXT NOT NULL,
 avatar TEXT NOT NULL DEFAULT '',
 bio TEXT NOT NULL DEFAULT '',
 created_at INTEGER NOT NULL,
 updated_at INTEGER NOT NULL,
 last_seen INTEGER NOT NULL DEFAULT 0,
 online INTEGER NOT NULL DEFAULT 0,
 language TEXT NOT NULL DEFAULT 'en'
);
CREATE TABLE IF NOT EXISTS sessions(
 token TEXT PRIMARY KEY,
 user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 created_at INTEGER NOT NULL,
 expires_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS conversations(
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 kind TEXT NOT NULL DEFAULT 'direct',
 title TEXT NOT NULL DEFAULT '',
 created_at INTEGER NOT NULL,
 updated_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS conversation_members(
 conversation_id INTEGER NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
 user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 joined_at INTEGER NOT NULL,
 role TEXT NOT NULL DEFAULT 'member',
 PRIMARY KEY(conversation_id,user_id)
);
CREATE TABLE IF NOT EXISTS messages(
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 conversation_id INTEGER NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
 sender_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 body TEXT NOT NULL,
 created_at INTEGER NOT NULL,
 edited_at INTEGER,
 deleted_at INTEGER,
 reply_to INTEGER REFERENCES messages(id) ON DELETE SET NULL,
 attachment_name TEXT NOT NULL DEFAULT '',
 attachment_type TEXT NOT NULL DEFAULT '',
 attachment_data TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS idx_messages_conversation ON messages(conversation_id,id);
CREATE INDEX IF NOT EXISTS idx_messages_sender ON messages(sender_id,id);
CREATE TABLE IF NOT EXISTS reactions(
 message_id INTEGER NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
 user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 emoji TEXT NOT NULL,
 created_at INTEGER NOT NULL,
 PRIMARY KEY(message_id,user_id,emoji)
);
CREATE TABLE IF NOT EXISTS reads(
 conversation_id INTEGER NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
 user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 message_id INTEGER NOT NULL,
 updated_at INTEGER NOT NULL,
 PRIMARY KEY(conversation_id,user_id)
);
CREATE TABLE IF NOT EXISTS blocks(
 blocker_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 blocked_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 created_at INTEGER NOT NULL,
 PRIMARY KEY(blocker_id,blocked_id)
);
`);

const app = express();
app.disable('x-powered-by');
app.use(express.json({ limit: '8mb' }));
app.use(express.urlencoded({ extended: false, limit: '1mb' }));
app.use(express.static(path.join(ROOT, 'public'), { extensions: ['html'] }));

const now = () => Date.now();
const json = (res, value, status=200) => res.status(status).json(value);
const clean = (value, max=4000) => String(value ?? '').trim().slice(0,max);
const usernameClean = (value) => String(value ?? '').normalize('NFKC').trim().toLowerCase().replace(/[^\p{L}\p{N}_.-]/gu,'').slice(0,32);
const passwordClean = (value) => String(value ?? '');
try { db.exec("ALTER TABLE users ADD COLUMN language TEXT NOT NULL DEFAULT 'en'"); } catch {}
const publicUser = (u) => u ? ({id:u.id,username:u.username,displayName:u.display_name,avatar:u.avatar,bio:u.bio,language:u.language||'en',createdAt:u.created_at,lastSeen:u.last_seen,online:!!u.online}) : null;
const token = () => crypto.randomBytes(32).toString('hex');
function hashPassword(password, salt=crypto.randomBytes(16).toString('hex')) {
  const hash = crypto.scryptSync(password, salt, 64).toString('hex');
  return {hash,salt};
}
function verifyPassword(password, salt, expected) {
  const actual = crypto.scryptSync(password, salt, 64).toString('hex');
  return crypto.timingSafeEqual(Buffer.from(actual,'hex'), Buffer.from(expected,'hex'));
}
function auth(req) {
  const header = String(req.headers.authorization || '');
  const bearer = header.startsWith('Bearer ') ? header.slice(7) : '';
  const cookie = String(req.headers.cookie || '').match(/(?:^|; )nova_session=([^;]+)/)?.[1] || '';
  const t = bearer || cookie;
  if (!t) return null;
  const row = db.prepare(`SELECT s.token,s.expires_at,u.* FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=?`).get(t);
  if (!row || row.expires_at < now()) return null;
  return { token:t, user:row };
}
function requireAuth(req,res,next) {
  const a = auth(req);
  if (!a) return json(res,{error:'Unauthorized'},401);
  req.auth = a;
  db.prepare('UPDATE users SET last_seen=?,online=1 WHERE id=?').run(now(),a.user.id);
  next();
}
function rateLimit(key, windowMs=3000, max=20) {
  const bucket = rateLimit.buckets.get(key) || {at:now(),count:0};
  if (now()-bucket.at > windowMs) { bucket.at=now(); bucket.count=0; }
  bucket.count++;
  rateLimit.buckets.set(key,bucket);
  return bucket.count <= max;
}
rateLimit.buckets = new Map();

function conversationForUsers(a,b) {
  const row = db.prepare(`SELECT c.id FROM conversations c JOIN conversation_members m1 ON m1.conversation_id=c.id AND m1.user_id=? JOIN conversation_members m2 ON m2.conversation_id=c.id AND m2.user_id=? WHERE c.kind='direct' LIMIT 1`).get(a,b);
  if (row) return row.id;
  const t=now();
  const tx=db.transaction(()=>{
    const result=db.prepare('INSERT INTO conversations(kind,title,created_at,updated_at) VALUES(?,?,?,?)').run('direct','',t,t);
    db.prepare('INSERT INTO conversation_members(conversation_id,user_id,joined_at) VALUES(?,?,?)').run(result.lastInsertRowid,a,t);
    db.prepare('INSERT INTO conversation_members(conversation_id,user_id,joined_at) VALUES(?,?,?)').run(result.lastInsertRowid,b,t);
    return result.lastInsertRowid;
  });
  return tx();
}
function membersOf(cid) { return db.prepare('SELECT user_id FROM conversation_members WHERE conversation_id=?').all(cid).map(x=>x.user_id); }
function conversationVisibleTo(userId,cid) { return !!db.prepare('SELECT 1 FROM conversation_members WHERE conversation_id=? AND user_id=?').get(cid,userId); }
function reactionList(mid) { return db.prepare('SELECT r.emoji,COUNT(*) count FROM reactions r WHERE r.message_id=? GROUP BY r.emoji ORDER BY count DESC').all(mid); }
function messageRow(row) {
  return {id:row.id,conversationId:row.conversation_id,senderId:row.sender_id,sender:publicUser(row),body:row.deleted_at?'This message was deleted':row.body,createdAt:row.created_at,editedAt:row.edited_at,deleted:!!row.deleted_at,replyTo:row.reply_to,attachment:row.attachment_name?{name:row.attachment_name,type:row.attachment_type,data:row.attachment_data}:null,reactions:reactionList(row.id)};
}
function broadcastUser(userId,event) { sendToUser(userId,event); }
function sendToUser(userId,event) {
  const set = sockets.get(userId) || new Set();
  const text=JSON.stringify(event);
  for(const ws of set) if(ws.readyState===1) ws.send(text);
}
function broadcastConversation(cid,event) { for(const id of membersOf(cid)) sendToUser(id,event); }

app.get('/api/health',(req,res)=>json(res,{ok:true,time:now(),database:'sqlite',version:1}));
app.post('/api/auth/register',(req,res)=>{
  const username=usernameClean(req.body.username);
  const password=passwordClean(req.body.password);
  const displayName=clean(req.body.displayName || username,64);
  const language=['en','uk','ru'].includes(req.body.language)?req.body.language:'en';
  if(!rateLimit('register:'+req.ip,60000,10)) return json(res,{error:'Too many attempts'},429);
  if(username.length<3) return json(res,{error:'Username must contain at least 3 characters'},400);
  if(password.length<6) return json(res,{error:'Password must contain at least 6 characters'},400);
  const exists=db.prepare('SELECT id FROM users WHERE username=?').get(username);
  if(exists) return json(res,{error:'Username is already taken'},409);
  const {hash,salt}=hashPassword(password); const t=now();
  const result=db.prepare('INSERT INTO users(username,display_name,password_hash,salt,created_at,updated_at,last_seen,online,language) VALUES(?,?,?,?,?,?,?,?,?)').run(username,displayName,hash,salt,t,t,t,1,language);
  const tok=token(); db.prepare('INSERT INTO sessions(token,user_id,created_at,expires_at) VALUES(?,?,?,?)').run(tok,result.lastInsertRowid,t,t+1000*60*60*24*30);
  res.setHeader('Set-Cookie',`nova_session=${tok}; HttpOnly; SameSite=Lax; Path=/; Max-Age=2592000`);
  return json(res,{user:publicUser(db.prepare('SELECT * FROM users WHERE id=?').get(result.lastInsertRowid)),token:tok});
});
app.post('/api/auth/login',(req,res)=>{
  const username=usernameClean(req.body.username); const password=passwordClean(req.body.password);
  if(!rateLimit('login:'+req.ip,60000,30)) return json(res,{error:'Too many attempts'},429);
  const u=db.prepare('SELECT * FROM users WHERE username=?').get(username);
  if(!u || !verifyPassword(password,u.salt,u.password_hash)) return json(res,{error:'Invalid username or password'},401);
  const tok=token(); const t=now(); db.prepare('INSERT INTO sessions(token,user_id,created_at,expires_at) VALUES(?,?,?,?)').run(tok,u.id,t,t+1000*60*60*24*30); db.prepare('UPDATE users SET online=1,last_seen=? WHERE id=?').run(t,u.id);
  res.setHeader('Set-Cookie',`nova_session=${tok}; HttpOnly; SameSite=Lax; Path=/; Max-Age=2592000`);
  json(res,{user:publicUser(u),token:tok});
});
app.post('/api/auth/logout',requireAuth,(req,res)=>{db.prepare('DELETE FROM sessions WHERE token=?').run(req.auth.token);db.prepare('UPDATE users SET online=0,last_seen=? WHERE id=?').run(now(),req.auth.user.id);res.setHeader('Set-Cookie','nova_session=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0');json(res,{ok:true});});
app.get('/api/me',requireAuth,(req,res)=>json(res,{user:publicUser(req.auth.user)}));
app.post('/api/auth/restore',requireAuth,(req,res)=>{ const old=req.auth.token; const t=now(); const tok=token(); db.prepare('INSERT INTO sessions(token,user_id,created_at,expires_at) VALUES(?,?,?,?)').run(tok,req.auth.user.id,t,t+1000*60*60*24*30); db.prepare('DELETE FROM sessions WHERE token=?').run(old); res.setHeader('Set-Cookie',`nova_session=${tok}; HttpOnly; SameSite=Lax; Path=/; Max-Age=2592000`); json(res,{token:tok,user:publicUser(req.auth.user)}); });

app.patch('/api/me',requireAuth,(req,res)=>{
  const name=clean(req.body.displayName ?? req.auth.user.display_name,64); const bio=clean(req.body.bio ?? req.auth.user.bio,240); const avatar=clean(req.body.avatar ?? req.auth.user.avatar,100000);
  if(name.length<1) return json(res,{error:'Display name is required'},400);
  db.prepare('UPDATE users SET display_name=?,bio=?,avatar=?,updated_at=? WHERE id=?').run(name,bio,avatar,now(),req.auth.user.id);
  const u=db.prepare('SELECT * FROM users WHERE id=?').get(req.auth.user.id); json(res,{user:publicUser(u)}); broadcastUser(req.auth.user.id,{type:'profile:update',user:publicUser(u)});
});
app.get('/api/users/search',requireAuth,(req,res)=>{
  const q=String(req.query.q ?? '').normalize('NFKC').trim().slice(0,64);
  if(!q) return json(res,{users:[]});
  const like='%'+q.replace(/[\%_]/g,'')+'%';
  const rows=db.prepare(`SELECT * FROM users WHERE id<>? AND (username LIKE ? COLLATE NOCASE OR display_name LIKE ? COLLATE NOCASE) ORDER BY CASE WHEN username=? THEN 0 WHEN username LIKE ? THEN 1 ELSE 2 END, online DESC, display_name COLLATE NOCASE LIMIT 30`).all(req.auth.user.id,like,like,q.toLowerCase(),q.toLowerCase()+'%');
  json(res,{users:rows.map(publicUser)});
});
app.post('/api/users/:id/block',requireAuth,(req,res)=>{const id=Number(req.params.id);if(!id||id===req.auth.user.id)return json(res,{error:'Invalid user'},400);db.prepare('INSERT OR IGNORE INTO blocks(blocker_id,blocked_id,created_at) VALUES(?,?,?)').run(req.auth.user.id,id,now());json(res,{ok:true});});
app.delete('/api/users/:id/block',requireAuth,(req,res)=>{db.prepare('DELETE FROM blocks WHERE blocker_id=? AND blocked_id=?').run(req.auth.user.id,Number(req.params.id));json(res,{ok:true});});

app.post('/api/chats/direct',requireAuth,(req,res)=>{
  const other=Number(req.body.userId); if(!other||other===req.auth.user.id) return json(res,{error:'Invalid user'},400);
  if(!db.prepare('SELECT id FROM users WHERE id=?').get(other)) return json(res,{error:'User not found'},404);
  const cid=conversationForUsers(req.auth.user.id,other); json(res,{conversation:getConversation(cid,req.auth.user.id)});
});
function getConversation(cid,viewer){
  const c=db.prepare('SELECT * FROM conversations WHERE id=?').get(cid); if(!c)return null;
  const members=db.prepare('SELECT u.* FROM conversation_members m JOIN users u ON u.id=m.user_id WHERE m.conversation_id=?').all(cid);
  const last=db.prepare('SELECT * FROM messages WHERE conversation_id=? ORDER BY id DESC LIMIT 1').get(cid);
  const read=db.prepare('SELECT message_id FROM reads WHERE conversation_id=? AND user_id=?').get(cid,viewer);
  const lastReadId=read?.message_id||0;
  const unreadCount=db.prepare('SELECT COUNT(*) count FROM messages WHERE conversation_id=? AND id>? AND sender_id!=? AND deleted_at IS NULL').get(cid,lastReadId,viewer).count;
  return {id:c.id,kind:c.kind,title:c.title,createdAt:c.created_at,updatedAt:c.updated_at,members:members.map(publicUser),lastMessage:last?messageRow(last):null,lastReadId,unreadCount};
}
app.get('/api/chats',requireAuth,(req,res)=>{
  const ids=db.prepare('SELECT conversation_id FROM conversation_members WHERE user_id=?').all(req.auth.user.id).map(x=>x.conversation_id);
  json(res,{conversations:ids.map(id=>getConversation(id,req.auth.user.id)).filter(Boolean).sort((a,b)=>b.updatedAt-a.updatedAt)});
});
app.get('/api/chats/:id/messages',requireAuth,(req,res)=>{
  const cid=Number(req.params.id); if(!conversationVisibleTo(req.auth.user.id,cid))return json(res,{error:'Forbidden'},403);
  const before=Number(req.query.before)||0; const limit=Math.min(100,Math.max(1,Number(req.query.limit)||50));
  const rows=before?db.prepare('SELECT m.*,u.id uid,u.username,u.display_name,u.avatar,u.bio,u.created_at ucreated,u.last_seen,u.online FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.conversation_id=? AND m.id<? ORDER BY m.id DESC LIMIT ?').all(cid,before,limit):db.prepare('SELECT m.*,u.id uid,u.username,u.display_name,u.avatar,u.bio,u.created_at ucreated,u.last_seen,u.online FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.conversation_id=? ORDER BY m.id DESC LIMIT ?').all(cid,limit);
  const messages=rows.map(r=>messageRow({id:r.id,conversation_id:r.conversation_id,sender_id:r.sender_id,body:r.body,created_at:r.created_at,edited_at:r.edited_at,deleted_at:r.deleted_at,reply_to:r.reply_to,attachment_name:r.attachment_name,attachment_type:r.attachment_type,attachment_data:r.attachment_data,avatar:r.avatar,username:r.username,display_name:r.display_name,bio:r.bio,last_seen:r.last_seen,online:r.online})).reverse();
  json(res,{messages,hasMore:rows.length===limit});
});
app.post('/api/chats/:id/messages',requireAuth,(req,res)=>{
  const cid=Number(req.params.id); if(!conversationVisibleTo(req.auth.user.id,cid))return json(res,{error:'Forbidden'},403); if(!rateLimit('msg:'+req.auth.user.id,5000,60))return json(res,{error:'Too many messages'},429);
  const body=clean(req.body.body,10000); const replyTo=Number(req.body.replyTo)||null; const attachment=req.body.attachment||null;
  if(!body && !attachment) return json(res,{error:'Message is empty'},400);
  if(body.length>10000)return json(res,{error:'Message is too long'},400);
  if(db.prepare('SELECT 1 FROM blocks WHERE blocker_id IN (SELECT user_id FROM conversation_members WHERE conversation_id=?) AND blocked_id IN (SELECT user_id FROM conversation_members WHERE conversation_id=?) LIMIT 1').get(cid,cid)) return json(res,{error:'Chat is blocked'},403);
  const t=now(); const result=db.prepare('INSERT INTO messages(conversation_id,sender_id,body,created_at,reply_to,attachment_name,attachment_type,attachment_data) VALUES(?,?,?,?,?,?,?,?)').run(cid,req.auth.user.id,body,t,replyTo,attachment?.name||'',attachment?.type||'',attachment?.data||'');
  db.prepare('UPDATE conversations SET updated_at=? WHERE id=?').run(t,cid);
  const row=db.prepare('SELECT m.*,u.* FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.id=?').get(result.lastInsertRowid); const msg=messageRow(row);
  broadcastConversation(cid,{type:'message:new',message:msg}); json(res,{message:msg});
});
app.patch('/api/messages/:id',requireAuth,(req,res)=>{
  const id=Number(req.params.id); const m=db.prepare('SELECT * FROM messages WHERE id=?').get(id); if(!m)return json(res,{error:'Not found'},404); if(m.sender_id!==req.auth.user.id)return json(res,{error:'Forbidden'},403); if(m.deleted_at)return json(res,{error:'Deleted'},400);
  const body=clean(req.body.body,10000);if(!body)return json(res,{error:'Message is empty'},400);const t=now();db.prepare('UPDATE messages SET body=?,edited_at=? WHERE id=?').run(body,t,id);const row=db.prepare('SELECT m.*,u.* FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.id=?').get(id);const msg=messageRow(row);broadcastConversation(m.conversation_id,{type:'message:update',message:msg});json(res,{message:msg});
});
app.delete('/api/messages/:id',requireAuth,(req,res)=>{const id=Number(req.params.id);const m=db.prepare('SELECT * FROM messages WHERE id=?').get(id);if(!m)return json(res,{error:'Not found'},404);if(m.sender_id!==req.auth.user.id)return json(res,{error:'Forbidden'},403);db.prepare('UPDATE messages SET deleted_at=?,body=? WHERE id=?').run(now(),'This message was deleted',id);const row=db.prepare('SELECT m.*,u.* FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.id=?').get(id);const msg=messageRow(row);broadcastConversation(m.conversation_id,{type:'message:update',message:msg});json(res,{message:msg});});
app.post('/api/messages/:id/reactions',requireAuth,(req,res)=>{const id=Number(req.params.id);const emoji=clean(req.body.emoji,16);const m=db.prepare('SELECT * FROM messages WHERE id=?').get(id);if(!m||!emoji)return json(res,{error:'Invalid reaction'},400);const existing=db.prepare('SELECT 1 FROM reactions WHERE message_id=? AND user_id=? AND emoji=?').get(id,req.auth.user.id,emoji);if(existing)db.prepare('DELETE FROM reactions WHERE message_id=? AND user_id=? AND emoji=?').run(id,req.auth.user.id,emoji);else db.prepare('INSERT INTO reactions(message_id,user_id,emoji,created_at) VALUES(?,?,?,?)').run(id,req.auth.user.id,emoji,now());broadcastConversation(m.conversation_id,{type:'message:reactions',messageId:id,reactions:reactionList(id)});json(res,{reactions:reactionList(id)});});
app.post('/api/chats/:id/read',requireAuth,(req,res)=>{const cid=Number(req.params.id);if(!conversationVisibleTo(req.auth.user.id,cid))return json(res,{error:'Forbidden'},403);const mid=Number(req.body.messageId)||0;db.prepare('INSERT INTO reads(conversation_id,user_id,message_id,updated_at) VALUES(?,?,?,?) ON CONFLICT(conversation_id,user_id) DO UPDATE SET message_id=excluded.message_id,updated_at=excluded.updated_at').run(cid,req.auth.user.id,mid,now());broadcastConversation(cid,{type:'read:update',conversationId:cid,userId:req.auth.user.id,messageId:mid});json(res,{ok:true});});
app.get('/api/search/messages',requireAuth,(req,res)=>{const q=clean(req.query.q,100);if(q.length<2)return json(res,{messages:[]});const like='%'+q.replace(/[%_]/g,'')+'%';const rows=db.prepare(`SELECT m.*,u.* FROM messages m JOIN users u ON u.id=m.sender_id JOIN conversation_members cm ON cm.conversation_id=m.conversation_id AND cm.user_id=? WHERE m.body LIKE ? AND m.deleted_at IS NULL ORDER BY m.id DESC LIMIT 100`).all(req.auth.user.id,like);json(res,{messages:rows.map(messageRow)});});

app.use((req,res)=>res.sendFile(path.join(ROOT,'public','index.html')));

const server=http.createServer(app);
const wss=new WebSocketServer({server,path:'/ws'});
const sockets=new Map();
function addSocket(uid,ws){if(!sockets.has(uid))sockets.set(uid,new Set());sockets.get(uid).add(ws);db.prepare('UPDATE users SET online=1,last_seen=? WHERE id=?').run(now(),uid);}
function removeSocket(uid,ws){const set=sockets.get(uid);if(!set)return;set.delete(ws);if(!set.size){sockets.delete(uid);db.prepare('UPDATE users SET online=0,last_seen=? WHERE id=?').run(now(),uid);}}
wss.on('connection',(ws,req)=>{
  const u=new URL(req.url,'http://localhost');const cookieHeader=String(req.headers.cookie||'');const cookieToken=cookieHeader.match(/(?:^|; )nova_session=([^;]+)/)?.[1]||'';const t=u.searchParams.get('token')||cookieToken;const session=db.prepare('SELECT s.*,u.* FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=? AND s.expires_at>?').get(t,now());if(!session){ws.close(1008,'Unauthorized');return;}const uid=session.user_id;addSocket(uid,ws);ws.send(JSON.stringify({type:'connected',user:publicUser(session)}));
  ws.on('message',raw=>{try{
    const data=JSON.parse(raw.toString());
    if(data.type==='typing'){
      const cid=Number(data.conversationId);
      if(conversationVisibleTo(uid,cid))broadcastConversation(cid,{type:'typing',conversationId:cid,userId:uid,active:!!data.active});
    }
    if(data.type==='presence'){db.prepare('UPDATE users SET online=?,last_seen=? WHERE id=?').run(data.online?1:0,now(),uid);}
    const callTypes=new Set(['call:invite','call:offer','call:answer','call:ice','call:end','call:reject']);
    if(callTypes.has(data.type)){
      const target=Number(data.toUserId);
      const cid=Number(data.conversationId);
      if(!target || !cid || target===uid || !conversationVisibleTo(uid,cid) || !conversationVisibleTo(target,cid)) return;
      const event={...data,type:data.type,fromUserId:uid,fromUser:publicUser(session),toUserId:target,conversationId:cid};
      sendToUser(target,event);
    }
  }catch{}});
  ws.on('close',()=>removeSocket(uid,ws));ws.on('error',()=>removeSocket(uid,ws));
});
setInterval(()=>{const cutoff=now()-1000*60*5;db.prepare('UPDATE users SET online=0 WHERE online=1 AND last_seen<?').run(cutoff);db.prepare('DELETE FROM sessions WHERE expires_at<?').run(now());},60000);
const PORT=Number(process.env.PORT)||3000;
server.listen(PORT,()=>console.log(`Nova Messenger running at http://localhost:${PORT}`));

